begin;
create temp table _kba231col(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kba231col values (74, $kba231col$[{"t":"list","id":"a2-2-3-1-b1","imp":"core","items":["1、==程序设计语言：主要用于描述算法，也称算法语言；==","2、==程序设计语言分类：机器语言（低级语言，计算机可以直接识别执行）、汇编语言（低级语言）、高级语言（如C,C#等）==","3、==机器语言==","==（1）机器语言就是计算机的指令系统，指令是使用二进制编码表示的。==","==（2）机器语言使用二进制代码编写，可以被计算机==@@直接识别并执行@@==，不需要翻译==","==（3）机器语言编写的程序记不住、难理解、编程效率低、不易维护，但是执行效率高==","==（4）机器语言对机器（硬件）有依赖性，移值性比较差。==","==（5）现在已经==@@不直接@@==用机器语言编写程序==","（6）举例：在MIPS 计算机上求最大公约数（GCD)的机器程序（16 进制表示）"],"title":"","ordered":false},{"h":256,"t":"img","w":1350,"id":"a2-2-3-1-b2","imp":"normal","src":"/kb-assets/theory/p33_r0_bc42df3ce9a6d5c6.png","title":""},{"t":"list","id":"a2-2-3-1-b3","imp":"core","items":["3、==汇编语言==","==（1）汇编语言是用助记符来表示机器指令中的操作符号与操作数。==","==（2）汇编语言是面向机器的程序设计语言（对机器仍有依赖性），属于低级语言==","==（3）汇编语言程序操作数直接使用十进制表示，程序相对容易理解==","（4）举例："],"title":"","ordered":false},{"h":301,"t":"img","w":956,"id":"a2-2-3-1-b4","imp":"normal","src":"/kb-assets/theory/p34_r0_9a62a18d2a73123d.png","title":""},{"t":"list","id":"a2-2-3-1-b5","imp":"core","items":["4、==高级语言==","==（1）高级语言（按近自然语言）容易理解、记忆和使用，降低了编程难度。==","==（2）高级语言克服汇编语言的缺陷，提高编程和维护效率==","==（3）高级语言程序移值性好，对硬件不太依赖==","==（4）高级语言对使用的符号、词汇、语法和语义等各种语言成分都有严格的规定==","（5）举例：C 语言举例"],"title":"","ordered":false},{"h":607,"t":"img","w":615,"id":"a2-2-3-1-b6","imp":"normal","src":"/kb-assets/theory/p34_r1_dd36c456721a71d4.png","title":""},{"t":"list","id":"a2-2-3-1-b5b","imp":"core","items":["5、==程序设计语言的处理系统（翻译系统）==：==源程序经翻译程序转换为目标程序==。","1）汇编语言：汇编语言源程序经汇编程序（汇编器）翻译为机器语言目标程序。","2）高级语言：（笔译）源程序经编译程序（编译器）翻译为机器语言目标程序，可供多次执行； （口译）源程序经解释程序（解释器）边翻译边执行，不产生目标程序。 编译过程：编辑—编译—连接—运行。","6、==语言处理与算法基础==：^^机器语言^^：==二进制编写==，对硬件依赖强，不易移植，可以直接被计算机执行，运行速度最快，不易记忆和理解。 汇编语言：用助记符代替操作码和操作数，需汇编程序翻译，具有机器语言移植性差的缺点。 高级语言：算法语言，易记忆和理解，通用性、可移植性强，便于维护，运行速度慢。 高级语言基本成分：数据成分（数据类型和数据结构）、运算成分（算术运算和逻辑运算）、控制成分（顺序、条件和循环）、传输成分（输入和输出）。 系统开发：正文编辑—翻译—连接编辑—装入—执行。 汇编程序：把汇编语言翻译成机器语言。","7、==SQL 查询与排序==：^^查询学生表中男生的记录^^：SELECT 学号, 姓名, 性别 FROM 学生 WHERE 性别 '男' 按学号降序输出： SELECT 学号, 姓名, 性别 FROM 学生 ORDER BY 学号 DESC","8、^^计算机语言的发展与分类^^：==计算机语言的发展阶段==：","^^机器语言：由 0 和 1 组成的指令^^。","^^汇编语言：用英文字母和数字表示指令^^。","^^高级语言：接近于人的自然语言和数学语言^^，分为面向过程的语言（非结构化的语言、结构化语言）和面向对象的语言。","9、^^文件管理与程序设计语言^^：^^文件管理强调的是对外存的管理^^，例如 Windows 对外存的文件采用树状的目录管理方式，也就是文件夹的管理方式。","10、==程序设计语言==：程序设计语言就是人类和计算机交流的语言。计算机只认识二进制，所以只能识别二进制语言，也就是机器语言。BIOS 芯片里面存放的就是机器语言。高级语言程序和汇编语言程序都需要翻译成机器语言程序才能被计算机执行。","11、^^软件发展的三个阶段^^：","==第一阶段==：^^机器语言和汇编语言阶段^^。","==第二阶段==：^^高级语言（如 FORTRAN）阶段^^，操作系统出现，软件危机随之产生。","==第三阶段==：^^软件工程阶段^^，以工程化方法高质量、高效率地开发软件。","软件危机的根源是软件开发方式难以适应硬件性能与需求规模的快速增长。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-3-1-b7","imp":"core","kind":"tip","text":"程序设计语言演进经历三阶段：==第一代机器语言（纯二进制代码，CPU 唯一能直接识别与执行的语言）==；==第二代汇编语言（使用助记符表示指令，需经汇编程序翻译为机器码）==；==第三代高级语言（面向过程如 C、面向对象如 Java/C++，语法接近自然语言和数学表达式）==。","title":"考向复习提示：程序设计语言三阶段发展脉络"},{"t":"callout","id":"a2-2-3-1-b8","imp":"core","kind":"trap","text":"专转本单选常考：==机器语言和汇编语言统称为“低级语言”（面向硬件机器的语言）==；很多考生因汇编语言有英文助记符误将其归入高级语言；记住：凡是依赖具体 CPU 寄存器和硬件指令架构的语言都是低级语言，只有与具体硬件指令集解耦的才是高级语言！","title":"高频易错陷阱：低级语言 vs 高级语言划分界线"}]$kba231col$::jsonb, $kba231colse$A2-2.3.1 程序设计语言的分类。 1、程序设计语言：主要用于描述算法，也称算法语言； 2、程序设计语言分类：机器语言（低级语言，计算机可以直接识别执行）、汇编语言（低级语言）、高级语言（如C,C#等） 3、机器语言 （1）机器语言就是计算机的指令系统，指令是使用二进制编码表示的。 （2）机器语言使用二进制代码编写，可以被计算机直接识别并执行，不需要翻译 （3）机器语言编写的程序记不住、难理解、编程效率低、不易维护，但是执行效率高 （4）机器语言对机器（硬件）有依赖性，移值性比较差。 （5）现在已经不直接用机器语言编写程序 （6）举例：在MIPS 计算机上求最大公约数（GCD)的机器程序（16 进制表示） 3、汇编语言 （1）汇编语言是用助记符来表示机器指令中的操作符号与操作数。 （2）汇编语言是面向机器的程序设计语言（对机器仍有依赖性），属于低级语言 （3）汇编语言程序操作数直接使用十进制表示，程序相对容易理解 （4）举例： 4、高级语言 （1）高级语言（按近自然语言）容易理解、记忆和使用，降低了编程难度。 （2）高级语言克服汇编语言的缺陷，提高编程和维护效率 （3）高级语言程序移值性好，对硬件不太依赖 （4）高级语言对使用的符号、词汇、语法和语义等各种语言成分都有严格的规定 （5）举例：C 语言举例 5、程序设计语言的处理系统（翻译系统）：源程序经翻译程序转换为目标程序。 1）汇编语言：汇编语言源程序经汇编程序（汇编器）翻译为机器语言目标程序。 2）高级语言：（笔译）源程序经编译程序（编译器）翻译为机器语言目标程序，可供多次执行； （口译）源程序经解释程序（解释器）边翻译边执行，不产生目标程序。 编译过程：编辑—编译—连接—运行。 6、语言处理与算法基础：机器语言：二进制编写，对硬件依赖强，不易移植，可以直接被计算机执行，运行速度最快，不易记忆和理解。 汇编语言：用助记符代替操作码和操作数，需汇编程序翻译，具有机器语言移植性差的缺点。 高级语言：算法语言，易记忆和理解，通用性、可移植性强，便于维护，运行速度慢。 高级语言基本成分：数据成分（数据类型和数据结构）、运算成分（算术运算和逻辑运算）、控制成分（顺序、条件和循环）、传输成分（输入和输出）。 系统开发：正文编辑—翻译—连接编辑—装入—执行。 汇编程序：把汇编语言翻译成机器语言。 7、SQL 查询与排序：查询学生表中男生的记录：SELECT 学号, 姓名, 性别 FROM 学生 WHERE 性别 '男' 按学号降序输出： SELECT 学号, 姓名, 性别 FROM 学生 ORDER BY 学号 DESC 8、计算机语言的发展与分类：计算机语言的发展阶段： 机器语言：由 0 和 1 组成的指令。 汇编语言：用英文字母和数字表示指令。 高级语言：接近于人的自然语言和数学语言，分为面向过程的语言（非结构化的语言、结构化语言）和面向对象的语言。 9、文件管理与程序设计语言：文件管理强调的是对外存的管理，例如 Windows 对外存的文件采用树状的目录管理方式，也就是文件夹的管理方式。 10、程序设计语言：程序设计语言就是人类和计算机交流的语言。计算机只认识二进制，所以只能识别二进制语言，也就是机器语言。BIOS 芯片里面存放的就是机器语言。高级语言程序和汇编语言程序都需要翻译成机器语言程序才能被计算机执行。 11、软件发展的三个阶段： 第一阶段：机器语言和汇编语言阶段。 第二阶段：高级语言（如 FORTRAN）阶段，操作系统出现，软件危机随之产生。 第三阶段：软件工程阶段，以工程化方法高质量、高效率地开发软件。 软件危机的根源是软件开发方式难以适应硬件性能与需求规模的快速增长。 考向复习提示：程序设计语言三阶段发展脉络 程序设计语言演进经历三阶段：第一代机器语言（纯二进制代码，CPU 唯一能直接识别与执行的语言）；第二代汇编语言（使用助记符表示指令，需经汇编程序翻译为机器码）；第三代高级语言（面向过程如 C、面向对象如 Java/C++，语法接近自然语言和数学表达式）。 高频易错陷阱：低级语言 vs 高级语言划分界线 专转本单选常考：机器语言和汇编语言统称为“低级语言”（面向硬件机器的语言）；很多考生因汇编语言有英文助记符误将其归入高级语言；记住：凡是依赖具体 CPU 寄存器和硬件指令架构的语言都是低级语言，只有与具体硬件指令集解耦的才是高级语言！$kba231colse$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kba231col loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
